-- GENERATED by `wfj generate` from data/gossip/gossip-5a.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["5a03b936d7bc4c39"] = { "Siamo noi a dover sferrare il primo colpo. Non possiamo permetterci di ripetere gli errori del passato...", "." },
  ["5a184a8dccfb032f"] = { "%s aspetta che le guardie non siano più in vista.", "." },
  ["5a228ddab4a8787b"] = { "Sartoria", "." },
  ["5a268560d21abdb8"] = { "Quante bende ha raccolto finora l'⟦Alliance=Alleanza⟧?", "." },
  ["5a2a9246dfb0c19d"] = { "Che bello vedere che stai così bene, Harlan. E spero di rivederti presto...", "." },
  ["5a3332b6b1431c41"] = { "La ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧ si trova nell'angolo meridionale della ⟦Alterac Valley=Valle d'Alterac⟧ e protegge il ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧, patria del clan di orchi che porta lo stesso nome. Tutti i territori dell'⟦Horde=Orda⟧ nella ⟦Alterac Valley=Valle d'Alterac⟧ derivano da questo luogo di potere.\n\nLa ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧ è stata rasa al suolo ed è in ricostruzione.", "." },
  ["5a37e8e153d6f87d"] = { "Ora senti il dolore...", "." },
  ["5a3851853bf8d3af"] = { "Questo sarà il mio miglior esperimento!", "." },
  ["5a38a1b8ebf0a522"] = { "I miei artigli faranno a brandelli il tuo misero corpo, {race}.", "." },
  ["5a393584a830e52a"] = { "%s quasi va in frantumi!", "." },
  ["5a48dee32e206165"] = { "C'è un tempo e un luogo per ogni cosa, anche per il riposo. Sul lato ovest del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧, il locandiere Kauth gestisce una casa lunga per chi cerca riposo. Lo troverai lì.", "." },
  ["5a4be775c05bcc4f"] = { "Quali scoperte?", "." },
  ["5a4df4e99cdcb522"] = { "Eccone uno! Per l'⟦Horde=Orda⟧!", "." },
  ["5a59ac57d573e631"] = { "<Gli occhi di Tarsis si illuminano.>\n\nL'ho stretto una volta... L'ho stretto nonostante gli avvertimenti del Kirin Tor. L'ho stretto, mortale... Potere senza fine. Il potere di fare ciò che desideravo, come lo desideravo. E altrettanto in fretta mi è stato tolto. Ma l'avevo assaggiato... E quel sapore è bastato.", "." },
  ["5a5bb1e76798d7de"] = { "Guarda! Laggiù, sulla parete del tunnel!", "." },
  ["5a63ac66057f2b22"] = { "Il nostro comandante è caduto! È giunta l'ora della vendetta! Cavalieri dei montoni, alla carica!!!!!!", "." },
  ["5a64960dd310fa56"] = { "Conosco qualcuno da queste parti che pratica una professione o due. A quale professione stai pensando?", "." },
  ["5a67275b6a6f11f7"] = { "Quanto da fare! Non avevo tanto lavoro da quando mio cugino vaporizzò per sbaglio tutta la stoffa e il cuoio di Gnomeregan. Accidenti, che spifferi per un po'! Ah, {name}, quelli sì che erano bei tempi....", "." },
  ["5a6a5e82fe6548c0"] = { "Dov'è l'anziano Ferrocollo?", "." },
  ["5a7092e33ccf3b7e"] = { "Dammi un paio di minuti, {name}. Poco fa qui dentro c'è stato un po' di trambusto, e voglio solo assicurarmi che le acque si siano calmate. Ti parlerò presto.", "." },
  ["5a746335af5a163a"] = { "Hai davvero coraggio, se vuoi sfidare gli orrori che si celano oltre questa porta.", "." },
  ["5a7cc837bc1d5391"] = { "Mi hanno evocato! Intrusi, venite nella mia tenda e affrontate la morte!", "." },
  ["5a9092dc553ebfac"] = { "Chi sei? Dove mi trovo? Mi sento... così debole...", "." },
  ["5a91bec24c558082"] = { "Dov'è l'anziano Tiarafredda?", "." },
  ["5a9876911728b606"] = { "Sai dove posso trovare il ⟦Half Pendant of Aquatic Agility=Mezzo Pendente dell'Agilità Acquatica⟧?", "." },
  ["5a9fbddaf36d2b2c"] = { "Non fermerai la nostra ombra che si allarga, {class}. E ora... unisciti a noi! Unisciti alle schiere dei Prescelti!", "." },
  ["5aa83e08c7187ddc"] = { "Nessun traditore da quattro soldi impedirà alla polvere da sparo di arrivare a Ironband!", "." },
  ["5ab87d03a1215215"] = { "All'improvviso erano dappertutto.", "." },
  ["5aba764c9c6b66d0"] = { "Gli spiriti di questo luogo sono ostili a quelli della tua specie, {race}. Forse, se conquisterai questa torre in carne e ossa, potrò aiutarti.", "." },
  ["5abd49cbd79b4c96"] = { "Devi fare ciò che io non ho potuto: salvare i contadini che sono stati abbattuti mentre fuggivano da Stratholme.\n\nCammineranno verso la luce: devi assicurarti che sopravvivano. Se ne cadranno troppi, la nostra esistenza maledetta continuerà, e avrai fallito.\n\nOgni abilità, preghiera e incantesimo che hai imparato sarà messo alla prova. Che la Luce ti protegga, {name}.", "." },
  ["5abe50285d25a593"] = { "Come si usa la ⟦Cache of Mau'ari=Cassa di Mau'ari⟧?", "." },
  ["5ac97603abb3524c"] = { "<Kharan si schiarisce la voce.>\n\nAttraversammo la galleria della ⟦Searing Gorge=Gorgia Rovente⟧ ed entrammo nella landa devastata che forma la gola. Ripensandoci, c'era una calma inquietante. Gli unici pericoli che incontrammo furono gli animali della regione: creature che i miei uomini sistemarono senza fatica.\n\nRaggiungemmo il ⟦Blackrock Mountain=Massiccio Roccianera⟧ con relativa facilità e attraversammo la costruzione di pietra lavorata senza il minimo intoppo.", "." },
  ["5ad2cb011fd31998"] = { "Anello centrale. Tu vai!", "." },
  ["5ad64456eb32b6e7"] = { "Ascolta, pivello, ci aspetta la battaglia della vita contro gli insetti di ⟦Ahn'Qiraj=Ahn'qiraj⟧ e dobbiamo prepararci. Qui raccolgo lingotti di ferro. Al momento l'⟦Alliance=Alleanza⟧ ha solo $2002w lingotti di ferro, ma secondo le stime ce ne serviranno $2003w in tutto per lo sforzo bellico.", "." },
  ["5ad8cfcd73ff04c2"] = { "Dai l'ordine, comandante. Farò a pezzi la metà inferiore della loro base.", "." },
  ["5adeca0e9afe4d7d"] = { "Il tuo fetore attirerà ogni drago per miglia e miglia. Dimmi cosa vuoi, e in fretta.", "." },
  ["5adeed438e646800"] = { "Quindi avevo ragione sulle energie. Vediamo cosa dice l'altro tomo sull'argomento.", "." },
  ["5adff2e1bb9c5bbb"] = { "Come posso aiutare?", "." },
  ["5ae42b45f5540714"] = { "La grazia con cui combatto non è qualcosa che posso insegnarti, ma posso insegnarti a usare varie armi.", "." },
  ["5af37d407bacde5b"] = { "Non c'è scampo, neanche nella morte.", "." },
})
